--
-- Name: fn_log_driver_swap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_log_driver_swap() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Only log when the driver assignment actually changes
    IF (TG_OP = 'UPDATE' AND OLD.current_driver_id IS DISTINCT FROM NEW.current_driver_id) THEN

        INSERT INTO driver_assignments_history (bus_id, old_driver_id, new_driver_id, change_type)
        VALUES (
            NEW.bus_id,
            OLD.current_driver_id,
            NEW.current_driver_id,
            CASE
                WHEN OLD.current_driver_id IS NULL AND NEW.current_driver_id IS NOT NULL THEN 'ASSIGNED'
                WHEN OLD.current_driver_id IS NOT NULL AND NEW.current_driver_id IS NULL THEN 'UNASSIGNED'
                ELSE 'SWAPPED'
            END
        );

    ELSIF (TG_OP = 'INSERT' AND NEW.current_driver_id IS NOT NULL) THEN

        INSERT INTO driver_assignments_history (bus_id, old_driver_id, new_driver_id, change_type)
        VALUES (NEW.bus_id, NULL, NEW.current_driver_id, 'ASSIGNED');

    END IF;

    RETURN NEW;
END;
$$;


